import { useSyncExternalStore } from 'react';

interface SwState {
  /** The app shell is cached and will load without a network. */
  offlineReady: boolean;
  /** A new version was downloaded and is waiting for a reload. */
  needRefresh: boolean;
}

let state: SwState = { offlineReady: false, needRefresh: false };
const listeners = new Set<() => void>();
let registration: ServiceWorkerRegistration | undefined;

const set = (patch: Partial<SwState>) => {
  state = { ...state, ...patch };
  listeners.forEach((l) => l());
};

/**
 * Registers /sw.js (generated by scripts/build-sw.mjs during `npm run build`).
 * Does nothing in `next dev`: service workers exist only in production builds.
 */
export function initServiceWorker(): void {
  if (process.env.NODE_ENV !== 'production' || typeof navigator === 'undefined' || !('serviceWorker' in navigator)) return;

  navigator.serviceWorker
    .register('/sw.js', { scope: '/' })
    .then((reg) => {
      registration = reg;
      // Already installed on a previous visit.
      if (reg.active && !reg.waiting) set({ offlineReady: true });
      if (reg.waiting && navigator.serviceWorker.controller) set({ needRefresh: true });

      reg.addEventListener('updatefound', () => {
        const worker = reg.installing;
        if (!worker) return;
        worker.addEventListener('statechange', () => {
          if (worker.state !== 'installed') return;
          // With an existing controller this is an UPDATE; otherwise it's the first install.
          if (navigator.serviceWorker.controller) set({ needRefresh: true });
          else set({ offlineReady: true });
        });
      });
    })
    .catch((e) => console.warn('Service worker registration failed:', e));
}

/** Activate the waiting worker, then reload once it takes control. */
export function applyUpdate(): void {
  const waiting = registration?.waiting;
  if (!waiting) return;
  navigator.serviceWorker.addEventListener('controllerchange', () => window.location.reload(), { once: true });
  waiting.postMessage('SKIP_WAITING');
}

const subscribe = (cb: () => void) => {
  listeners.add(cb);
  return () => listeners.delete(cb);
};
const serverState: SwState = { offlineReady: false, needRefresh: false };

export function useServiceWorker(): SwState {
  return useSyncExternalStore(subscribe, () => state, () => serverState);
}
